import {WALL_ROLE} from './wall-roles.js';
const port=(id,face,a=3,b=5,height=2.5)=>({id,face,a,b,height,role:WALL_ROLE.CONNECTOR});
const wall=(a,b,extra={})=>({a,b,role:WALL_ROLE.ROOM,...extra});
const box=(x,z,w,d,h=.5,extra={})=>({x,z,w,d,h,color:'wood',...extra});
const root=(id,name,cells,use,zone)=>({id,name,generation:11,use,zone,color:zone==='housing'?'#a6b29e':zone==='research'?'#95aeb5':'#c2ad88',cells,ceiling:2.8,ports:[],walls:[],doors:[],solids:[],furniture:[],privateRooms:[],labels:[],roofAreas:cells.map(([x,z])=>({x:x*8,z:z*8,w:8,d:8,height:2.8}))});
const door=(id,a,b,label,swing=-90,extra={})=>({id,a,b,label,kind:'hinge',hinge:'a',swing,open:false,...extra});
export const DISTRICT_PURPOSE={RH1:'六室と廊下を持つ二連結住宅。Bで東へ移り共有廊下SH2を経由する居住街へ',CP1:'内部二層のカプセル棟。RH1と別々に搬送し上階の乗員も保持',MK1:'一チャンク三店舗・東西廊下と南北枝。Bでは住宅棟と別々に東へ搬送',SH1:'共有街路の西半。商業区の二経路を維持する可動設備の待機',SH2:'共有街路の東半。Bで第三層へ独立搬送して住宅群へ接続',LB1:'二連結研究所。Bでは東南へ運び入口を閉鎖し、Cで商店街へ再接続'};
export function expandStage11(bodies){
 const get=id=>bodies.find(b=>b.id===id);get('U4').ports.push(port('market','E',5.5,7.5));get('U2').ports.push(port('district','S',.3,1.9));
 const r=root('RH1','居住街・六つの扉と共用廊下',[[0,0],[1,0]],'residential','housing');r.ports=[port('entry','N',.3,1.9),port('capsule','E'),port('shops','S',.3,1.9)];
 for(let i=0;i<3;i++)for(const south of [false,true]){const x=2.6+i*4.3,w=i===2?4.8:4.3,z=south?5.3:.2,d=south?2.5:2.5,n=101+i+(south?3:0),front=south?5.3:2.7;r.privateRooms.push({x,z,w,d});r.doors.push(door('RH1-'+n,[x+1.1,front],[x+2.2,front],n+'号室',south?90:-90));r.furniture.push(box(x+w-1.3,south?6.05:.4,1,1.3));r.labels.push({name:n+'号',x:x+w/2,z:south?6.8:1.3});}
 r.labels.push({name:'居住街・共用廊下',x:9,z:4});bodies.push(r);
 const m=root('MK1','小商店通り・三店舗と折れた共用廊下',[[0,0]],'commerce','commerce');m.ports=[port('north','N',.3,1.9)];
 // Open counter north, a room shop SW, and a compact stall SE: no additional NPC/economy.
 m.walls=[wall([2.6,.3],[2.6,2.7],{height:2.3}),wall([2.6,.3],[5.8,.3],{height:2.3}),wall([5.8,.3],[5.8,2.7],{height:2.3}),wall([.3,5.3],[1.3,5.3]),wall([2.4,5.3],[3.4,5.3]),wall([3.4,5.3],[3.4,7.8]),wall([3.6,5.3],[3.6,7.7],{height:2.3}),wall([5.8,5.3],[5.8,7.7],{height:2.3})];
 m.doors=[door('MK1-room',[1.3,5.3],[2.4,5.3],'小店舗・室内へ',90)];m.furniture=[box(2.8,2.25,2.8,.4,.9),box(3.8,5.3,1.8,.4,.9),box(.5,7,1.5,.5,.8),box(2.8,.5,2.8,.35,.8),box(3.8,7.2,1.8,.35,.8)];m.labels=[{name:'カウンター店',x:4.2,z:1.5},{name:'室内店舗',x:1.7,z:6.6},{name:'小売台',x:4.7,z:6.5},{name:'商店通り',x:4,z:4}];bodies.push(m);
 for(const right of [false,true]){const b=root(right?'SH2':'SH1',right?'共有街路・東半と店舗':'共有街路・西半と店舗',[[0,0]],'commerce','commerce');b.sharedHalf=true;b.ports=[port('shared',right?'W':'E',.8,7.4),port('end','S',right?.3:6.1,right?1.9:7.7)];if(right)b.ports.push(port('north','N',.3,1.9),port('lab','E',5.5,7.5));else b.ports.push(port('entry','W',2.1,4.1));const face=right?2.2:5.8,back=right?7.6:.4;b.walls=[wall([face,.9],[face,5.3],{height:2.35}),wall([Math.min(face,back),.9],[Math.max(face,back),.9],{height:2.35})];if(!right){b.walls=[wall([5.8,.6],[5.8,1.9],{height:2.35}),wall([5.8,4.3],[5.8,5.3],{height:2.35})];b.furniture=[box(4.9,.8,.65,.8,.9),box(4.9,4.5,.65,.7,.9)];}else b.furniture=[box(2.45,1.2,.65,3.8,.9),box(6.7,1.3,.5,3.5,.75)];b.labels=[{name:right?'東半・片寄せ廊下':'西半・片寄せ廊下',x:right?1.1:6.9,z:4}];bodies.push(b);}
 const c=root('CP1','二階建てカプセル棟',[[0,0]],'residential','housing');c.capsule=true;c.ceiling=5.6;c.roofAreas=[{x:0,z:0,w:8,d:8,height:5.6}];c.ports=[port('entry','W')];
 for(const floor of [0,3])for(const south of [false,true]){const z=south?5.4:.2,n=(floor?201:101)+(south?1:0),a=south?5.9:.8,b=a+1.1;c.privateRooms.push({x:.2,z,w:2.7,d:2.4,floor,height:floor?2.6:2.84});c.doors.push(door('CP1-'+n,[2.9,a],[2.9,b],n+' カプセル',90,{floor,capsuleView:{camera:{x:2.5,y:floor+1.65,z:a+.55},look:{x:1.65,y:floor+1.25,z:a+.55},model:{x:1.65,y:floor,z:a+.55}}}));c.furniture.push(box(.35,z+.25,1,1.4,.4,{floor}));c.labels.push({name:n+' カプセル',x:1.45,z:z+1.2,floor});}bodies.push(c);
 const l=root('LB1','通り沿いの二連結研究所',[[0,0],[1,0]],'research','research');l.loadedInterior=true;l.ceiling=3.4;l.roofAreas=[{x:0,z:0,w:16,d:8,height:3.4}];l.ports=[{...port('entry','W',5.5,7.5),navInset:.55}];
 l.walls=[wall([1.2,0],[1.2,5.5],{exterior:true}),wall([1.2,7.5],[1.2,8],{exterior:true}),wall([1.2,3.1],[5.2,3.1]),wall([6.3,3.1],[10.8,3.1]),wall([11.9,3.1],[16,3.1]),wall([10,0],[10,3.1]),wall([3.2,5.2],[5.3,5.2]),wall([6.4,5.2],[11.4,5.2]),wall([12.5,5.2],[16,5.2]),wall([10,5.2],[10,8]),wall([3.2,5.2],[3.2,8])];
 l.doors=[door('LB1-left',[1.2,5.5],[1.2,6.5],'研究所・二枚扉',-90,{entrance:true}),door('LB1-right',[1.2,6.5],[1.2,7.5],'研究所・二枚扉',90,{hinge:'b',entrance:true}),door('LB1-main',[5.2,3.1],[6.3,3.1],'主研究室'),door('LB1-small',[10.8,3.1],[11.9,3.1],'小実験室'),door('LB1-work',[5.3,5.2],[6.4,5.2],'分析室',90),door('LB1-store',[11.4,5.2],[12.5,5.2],'保管室',90)];l.furniture=[box(3,.4,3,.7,.9),box(11,.4,3,.7,.9),box(7,6.7,2,.7,.9),box(14,6,1,1.5,1.1)];l.labels=[{name:'前室',x:2.2,z:6.5},{name:'主研究室',x:6,z:1.7},{name:'小実験室',x:13,z:1.7},{name:'分析室',x:6,z:6.6},{name:'保管室',x:13,z:6.6},{name:'研究所・内部廊下',x:8,z:4.2}];bodies.push(l);
 // Existing large rooms and stores remain; their area membership is descriptive, never a rigid transport group.
 for(const b of bodies)if(!b.zone)b.zone=b.use==='commerce'?'commerce':b.use==='residential'||['G3','A3','P9'].includes(b.id)?'housing':'service';
}
export function districtPlacements(phase,p){const b=phase==='B';return Object.assign(p,{MK1:{x:b?58.8:50.4,y:12.8,z:25.2},SH1:{x:58.8,y:0,z:11.8},SH2:b?{x:58.8,y:12.8,z:8.4}:{x:67.2,y:0,z:10.8},RH1:{x:b?58.8:50.4,y:12.8,z:16.8},CP1:{x:b?75.6:67.2,y:12.8,z:16.8},LB1:b?{x:84,y:0,z:16.8}:{x:75.6,y:0,z:10.8}});}
export const CAPSULE_FLOORS=[0,3];
export const CAPSULE_SLABS=[{x:0,z:0,w:5.4,d:8},{x:7.8,z:0,w:.2,d:8},{x:5.4,z:0,w:2.4,d:1.2},{x:5.4,z:6.6,w:2.4,d:1.4}];
export function capsuleSurface(x,z,fromY=0){if(x<0||x>8||z<0||z>8)return null;if(x>=5.4&&x<=7.8&&z>=1.2&&z<=6.6)return Math.max(0,Math.min(3,Math.ceil((6.6-z-1e-7)/.27)*.15));return fromY>1.5?3:0;}
